#include "stdlib/blas/ext/base/ndarray/slinspace.h"
#include "stdlib/blas/ext/base/slinspace.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include <stdbool.h>

/**
* Fills a one-dimensional single-precision floating-point ndarray with linearly spaced values over a specified interval.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray specifying the start of the interval.
*     -   a zero-dimensional ndarray specifying the end of the interval.
*     -   a zero-dimensional ndarray specifying whether to include the end of the interval when writing values to the input ndarray.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_slinspace( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];

	float start;
	float stop;
	bool endpoint;
	stdlib_ndarray_get_float32( arrays[ 1 ], NULL, &start );
	stdlib_ndarray_get_float32( arrays[ 2 ], NULL, &stop );
	stdlib_ndarray_get_bool( arrays[ 3 ], NULL, &endpoint );

	const CBLAS_INT N = stdlib_ndarray_dimension( x, 0 );
	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x );

	float *dataX = (float *)stdlib_ndarray_data( x );
	API_SUFFIX(stdlib_strided_slinspace_ndarray)( N, start, stop, endpoint, dataX, strideX, offsetX );
}
